const input = $input.first().json;
const source = input.external_source || input.externalSource || 'acquisition';
const externalId = String(input.external_id || input.externalId || input.parcelId || input._id || '');
if (!externalId) throw new Error('InsulaCRM adapter requires external_id, externalId, parcelId, or _id');
if (!input.first_name && !input.firstName) throw new Error('InsulaCRM adapter requires first_name/firstName');
if (!input.last_name && !input.lastName) throw new Error('InsulaCRM adapter requires last_name/lastName');
return [{ json: {
  external_id: externalId,
  external_source: source,
  first_name: input.first_name || input.firstName,
  last_name: input.last_name || input.lastName,
  phone: input.phone || null,
  email: input.email || null,
  source: input.source || input.lead_source || 'acquisition',
  notes: input.notes || JSON.stringify({ parcelId: input.parcelId || null, distressScore: input.distressScore || null, primaryDistress: input.primaryDistress || null, tier: input.tier || null, candidate_key: input.candidate_key || null, normalized_identity_key: input.normalized_identity_key || null, evidence_count: input.evidence_count ?? 0, evidence_source_types: input.evidence_source_types || [], matched_criteria: input.matched_criteria || [], evidence_status: input.evidence_status || null, normalization_warnings: input.normalization_warnings || [] }),
  property_address: input.property_address || input.address || null,
  property_city: input.property_city || input.city || null,
  property_state: input.property_state || input.state || null,
  property_zip: input.property_zip || input.zip || null,
  property_type: input.property_type || input.propertyType || input.listingType || null,
  utm_source: input.utm_source || null,
  utm_medium: input.utm_medium || null,
  utm_campaign: input.utm_campaign || null
} }];

const response = $input.first().json;
const input = $('Normalize Lead Payload').first().json;
return [{ json: {
  success: response.success !== false,
  duplicate: response.duplicate === true,
  lead_id: response.lead_id || null,
  property_id: response.property_id || null,
  external_id: response.external_id || input.external_id,
  external_source: response.external_source || input.external_source,
  insula_response: response
} }];
